widgets_values:
{
  "项目设置":{
    "任务类型":"根据提供的参考图制作九宫格拼图海报",人物面部保持不变
    "布局结构":"3x3 等距矩阵网格",
    "纵横比":"1:1 (正方形)",
    "视觉氛围":"高对比度、纯净、甜美、节日治愈"
},
"整体视觉风格":{
    "主背景":"纯净深红色 (#8B0000) 平整背景",
    "地面装饰":"底部铺设白色长毛绒地毯，质感蓬松",
    "光影效果":"明亮的影棚柔光，强调人物轮廓，减少阴影杂乱",
    "核心配色":["深红背景","纯净白服装","黑白条纹斑马"]
},
"人物服装方案（优化版）":{
    "上装/裙装":"纯白色法式复古连衣裙 (White Vintage French Dress)，带有精致的泡泡袖 (Puff Sleeves) 和荷叶边装饰，材质为挺括的棉麻或轻盈的蕾丝",
    "头饰":"白色蕾丝发带，顶部带有醒目的红色蝴蝶结（作为点睛之笔）",
    "发型":"黑色长发，自然微卷或直发，展现柔顺质感",
    "妆容":"干净的底妆，重点在于红唇，与背景色呼应"
},
"核心道具设定（亲昵斑马群）":{
    "形态":"所有斑马玩偶均为‘坐姿’ (Sitting Pose)，圆润可爱，黑白条纹清晰",
    "数量":"每格 2-3 只不同尺寸的斑马，形成簇拥感",
    "互动要求":"人物与斑马表现出极高的亲昵感（如脸贴脸、怀抱、依偎、摸头）"
},
"文字排版规范":{
    "字体样式":"白色手写书法字体，笔触自然",
    "层级要求":"文字作为背景元素，严格置于人物和斑马的后方，严禁遮挡任何主体部分",
    "内容要求":"每格一个不同的四字新年祝福语"
},
"九宫格详细分布":[
    {
      "位置":1,
      "人物动作":"侧坐，双手环抱一只中型坐姿斑马，脸颊贴在斑马背上",
      "斑马分布":"怀抱一只，身侧坐着一只小斑马",
      "文字内容":"新年快乐"
    },
    {
      "位置":2,
      "人物动作":"正坐，两只中型斑马靠在她肩膀两侧，她开心地闭眼微笑",
      "斑马分布":"左右各一只，呈现亲昵挤在一起的状态",
      "文字内容":"万事如意"
    },
    {
      "位置":3,
      "人物动作":"俯身趴在白色地毯上，双手托腮，面前坐着三只排开的小斑马",
      "斑马分布":"前方三只小型坐姿斑马，像在听她说话",
      "文字内容":"岁岁平安"
    },
    {
      "位置":4,
      "人物动作":"背靠着一只巨大的坐姿斑马，头轻轻后仰靠在斑马身上",
      "斑马分布":"身后大斑马，膝盖旁一只小斑马",
      "文字内容":"喜气洋洋"
    },
    {
      "位置":5,
      "人物动作":"坐在斑马群中心，双手在胸前比心，一只斑马坐在她腿上",
      "斑马分布":"被四只不同尺寸的坐姿斑马环绕簇拥",
      "文字内容":"大吉大利"
    },
    {
      "位置":6,
      "人物动作":"侧身坐着，与一只中型斑马‘碰鼻尖’，画面极具亲昵感",
      "斑马分布":"对面一只中型，身后一只小型斑马",
      "文字内容":"步步高升"
    },
    {
      "位置":7,
      "人物动作":"盘腿坐，两手各搂着一只斑马的脖子，笑容灿烂",
      "斑马分布":"左右各一只中型坐姿斑马",
      "文字内容":"好运连连"
    },
    {
      "位置":8,
      "人物动作":"坐姿，将一只小型斑马抱在怀里，并用额头抵住斑马",
      "斑马分布":"怀里一只，脚边坐着一只",
      "文字内容":"福星高照"
    },
    {
      "位置":9,
      "人物动作":"半躺在斑马堆里，一只手牵着斑马的蹄子，甜美看向镜头",
      "斑马分布":"周围堆满大大小小的坐姿斑马",
      "文字内容":"阖家欢乐"
    }
],
"约束与禁止":{
    "强制要求":[
      "服装必须是纯白色，严禁出现红色衣服",
      "所有斑马必须是坐姿，严禁站立",
      "文字必须在人物和斑马的图层之后",
      "严禁出现数字年份（如2025、2026）和英文字母",
      "保持九张图中人物的相貌和发型高度一致"
    ]
}
}
